          {
            "id": "N_B_BASIS",
            "type": "rule_application",
            "supported_state": "B以182960.00元实际交付额作为最初本金，成立及起息日为2022-01-12；题设下利率保护上限为年14.80%。22%利率中的超限部分不受保护，不据此将B整体认定无效。",
            "support": [
              "S03",
              "S04",
              "civil-code-2020:670",
              "civil-code-2020:679",
              "lending-2020-12:25",
              "lending-2020-12:26"
            ]
